#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    long long colSum[1000] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            long long val;
            scanf("%lld", &val);
            colSum[j] += val;
        }
    }

    long long min = colSum[0];
    for (int j = 1; j < M; j++) {
        if (colSum[j] < min) {
            min = colSum[j];
        }
    }

    printf("%lld\n", min);
    return 0;
}
